import { Accordion, Separator, Text } from "@chakra-ui/react";
import type { ConversationEvent, Flow } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

interface FlowEventInfoProps {
  event: ConversationEvent;
  flow?: Flow;
  onClose: () => void;
}

export const FlowEventInfo = ({ event, flow, onClose }: FlowEventInfoProps) => {
  return (
    <DetailView title="Flow event" onClose={onClose}>
      <InfoField label="Name" data-testid="event-slot-or-flow-name">
        <Text textStyle="sm" wordBreak="break-all">
          {flow?.name || event.flowId || "-"}
        </Text>
      </InfoField>

      <InfoField label="Description">
        <Text textStyle="sm">{flow?.description || "-"}</Text>
      </InfoField>

      <Separator mt="2" />

      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
